param([int[]]$DatasetSizes=@(100,1000,5000,10000),[int]$Warmups=5,[int]$Iterations=30,[int]$BackendPort=8081,[string]$EvaluationDatabase='crowd_feedback_eval')
$ErrorActionPreference='Stop'; Set-StrictMode -Version Latest
if($EvaluationDatabase -eq 'crowd_feedback'){throw 'SAFETY GUARD: evaluation database must never be crowd_feedback.'}
if($EvaluationDatabase -ne 'crowd_feedback_eval'){throw 'SAFETY GUARD: this harness permits only crowd_feedback_eval.'}
if($Warmups -lt 0 -or $Iterations -lt 1 -or $DatasetSizes.Where({$_ -lt 1}).Count){throw 'Dataset sizes/iterations must be positive.'}
$root=Split-Path -Parent $PSScriptRoot; $envFile=Join-Path $root '.env'; if(!(Test-Path $envFile)){throw 'Create local .env with database, JWT, APP_ADMIN_EMAIL and APP_ADMIN_PASSWORD configuration.'}
$config=@{}; Get-Content $envFile | Where-Object {$_ -match '^\s*[^#][^=]*='} | ForEach-Object {$k,$v=$_ -split '=',2;$config[$k.Trim()]=$v.Trim().Trim('"').Trim("'")}
foreach($key in @('DATABASE_PASSWORD','JWT_SECRET','APP_ADMIN_EMAIL','APP_ADMIN_PASSWORD')){if(!$config[$key]){throw "Missing $key in local .env; no fake evaluation credentials will be used."}}
$dbUser=if($config['DATABASE_USERNAME']){$config['DATABASE_USERNAME']}else{'crowd'}; $container='crowdtransportfeedback-m9-backend';$base="http://localhost:$BackendPort";$resultsDir=Join-Path $PSScriptRoot 'results';New-Item -ItemType Directory -Force $resultsDir|Out-Null
$out=Join-Path $resultsDir 'performance-results.csv';$metadata=Join-Path $resultsDir 'performance-environment.txt';Write-Warning "This run overwrites $out and $metadata"
function Compose([string[]]$Arguments){& docker compose --project-directory $root @Arguments;if($LASTEXITCODE){throw "docker compose failed: $($Arguments -join ' ')"}}
function Psql([string]$Database,[string]$Sql,[string[]]$Variables=@()){ $args=@('compose','--project-directory',$root,'exec','-T','postgres','psql','-v','ON_ERROR_STOP=1','-U',$dbUser,'-d',$Database)+$Variables; $Sql | & docker @args;if($LASTEXITCODE){throw 'PostgreSQL evaluation command failed.'} }
function Request([string]$Uri,[string]$Token){Invoke-RestMethod -Uri $Uri -Headers @{Authorization="Bearer $Token"} -Method Get}
function Timed([string]$Name,[string]$Uri,[string]$Token,[int]$Size){for($i=0;$i -lt $Warmups;$i++){[void](Request $Uri $Token)};$times=[System.Collections.Generic.List[double]]::new();$failures=0;for($i=0;$i -lt $Iterations;$i++){$sw=[Diagnostics.Stopwatch]::StartNew();try{[void](Request $Uri $Token);$sw.Stop();$times.Add($sw.Elapsed.TotalMilliseconds)}catch{$sw.Stop();$failures++;throw "Measured request failed for $Name; dataset aborted and no misleading row written: $($_.Exception.Message)"}};$sorted=@($times|Sort-Object);function NR([double]$p){$sorted[[Math]::Max(0,[Math]::Ceiling($p*$sorted.Count)-1)]};[pscustomobject]@{dataset_size=$Size;endpoint=$Name;warmup_count=$Warmups;iteration_count=$Iterations;success_count=$times.Count;failure_count=$failures;min_ms=[Math]::Round($sorted[0],3);average_ms=[Math]::Round(($times|Measure-Object -Average).Average,3);p50_ms=[Math]::Round((NR .50),3);p95_ms=[Math]::Round((NR .95),3);max_ms=[Math]::Round($sorted[-1],3)}}
$rows=@()
try{
 Compose @('up','-d','postgres'); Psql 'postgres' "SELECT 'CREATE DATABASE $EvaluationDatabase' WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname='$EvaluationDatabase')\gexec"
 & docker build -t crowdtransportfeedback-m9-backend-image (Join-Path $root 'backend');if($LASTEXITCODE){throw 'Backend image build failed.'}
 $postgresId=(& docker compose --project-directory $root ps -q postgres).Trim();$network=(& docker inspect $postgresId --format '{{range $k,$v := .NetworkSettings.Networks}}{{$k}}{{end}}').Trim()
 & docker rm -f $container 2>$null|Out-Null
 $run=@('run','-d','--rm','--name',$container,'--network',$network,'-p',"${BackendPort}:8080",'-e',"DATABASE_URL=jdbc:postgresql://postgres:5432/$EvaluationDatabase",'-e',"DATABASE_USERNAME=$dbUser",'-e',"DATABASE_PASSWORD=$($config.DATABASE_PASSWORD)",'-e',"JWT_SECRET=$($config.JWT_SECRET)",'-e',"APP_ADMIN_EMAIL=$($config.APP_ADMIN_EMAIL)",'-e',"APP_ADMIN_PASSWORD=$($config.APP_ADMIN_PASSWORD)",'-e',"APP_ADMIN_USERNAME=$(if($config.APP_ADMIN_USERNAME){$config.APP_ADMIN_USERNAME}else{'admin'})",'crowdtransportfeedback-m9-backend-image');& docker @run|Out-Null;if($LASTEXITCODE){throw 'Temporary evaluation backend failed to start.'}
 $ready=$false;for($i=0;$i -lt 60;$i++){try{Invoke-WebRequest "$base/actuator/health" -UseBasicParsing|Out-Null;$ready=$true;break}catch{Start-Sleep 2}};if(!$ready){throw 'Temporary backend did not become healthy.'}
 $auth=Invoke-RestMethod "$base/api/auth/login" -Method Post -ContentType 'application/json' -Body (@{email=$config.APP_ADMIN_EMAIL;password=$config.APP_ADMIN_PASSWORD}|ConvertTo-Json);$token=$auth.accessToken;if(!$token){throw 'Administrator authentication did not return an access token.'}
 foreach($size in $DatasetSizes){Psql $EvaluationDatabase (Get-Content (Join-Path $PSScriptRoot 'sql/reset-performance-data.sql') -Raw) @('-v',"evaluation_db=$EvaluationDatabase");Psql $EvaluationDatabase (Get-Content (Join-Path $PSScriptRoot 'sql/seed-performance-data.sql') -Raw) @('-v',"row_count=$size")
  $heatUri="$base/api/analytics/heatmap?metric=TRUST&transportType=METRO&line=M9EVAL&window=ALL";$heat=@(Request $heatUri $token);if(!$heat.Count -or !$heat[0].cellId){throw "Correctness failure: empty heatmap for $size"};$cell=[uri]::EscapeDataString($heat[0].cellId);$areaUri="$base/api/analytics/area?cellId=$cell&metric=TRUST&transportType=METRO&line=M9EVAL&window=ALL"
  $overview=Request "$base/api/admin/overview" $token;if([long]$overview.totalFeedbacks -ne $size){throw "Correctness failure: overview totalFeedbacks != $size"};$summaryUri="$base/api/admin/reporting/summary?window=ALL&transportType=METRO&line=M9EVAL";$summary=Request $summaryUri $token;if([long]$summary.feedbackCount -ne $size){throw "Correctness failure: summary feedbackCount != $size"};$adminFeedbackUri="$base/api/admin/feedback?transportType=METRO&line=M9EVAL&window=ALL&page=0&size=20";$adminRows=Request $adminFeedbackUri $token;if([long]$adminRows.totalElements -ne $size -or !@($adminRows.content).Count){throw 'Correctness failure: filtered admin feedback is incomplete'};[void](Request $areaUri $token)
  $targets=[ordered]@{analytics_heatmap=$heatUri;analytics_area=$areaUri;feedback_all="$base/api/feedback";admin_overview="$base/api/admin/overview";admin_reporting_summary=$summaryUri;admin_feedback=$adminFeedbackUri};foreach($entry in $targets.GetEnumerator()){$rows+=Timed $entry.Key $entry.Value $token $size}
 }
 $rows|Export-Csv -NoTypeInformation -Encoding utf8 $out
 $cpu=(Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue|Select-Object -First 1 -ExpandProperty Name);$ram=(Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue).TotalPhysicalMemory
 @("evaluation_timestamp=$(Get-Date -Format o)","os=$([Environment]::OSVersion.VersionString)","cpu_model=$cpu","logical_processors=$([Environment]::ProcessorCount)","total_ram_bytes=$ram","java_version=$((& java -version 2>&1|Select-Object -First 1) -replace '[\r\n]',' ')","docker_version=$(& docker version --format '{{.Client.Version}}')","postgresql_image=postgres:17-alpine","spring_boot_version=3.5.6","warmup_count=$Warmups","measured_iterations=$Iterations","dataset_sizes=$($DatasetSizes -join ',')","temporary_backend_port=$BackendPort","percentile_method=nearest-rank")|Set-Content -Encoding utf8 $metadata
} finally {& docker rm -f $container 2>$null|Out-Null}
Write-Host "Wrote $out and $metadata. Keep these results tied to this environment and commit SHA."
